// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

contract SmartToken {
    // Basic token attributes
    string private _tokenName;
    string private _tokenSymbol;
    uint8 private _tokenDecimals;
    uint256 private _totalTokens;

    // Mapping of addresses to their balances
    mapping(address => uint256) private _balances;
    // Mapping of owner => (spender => allowance)
    mapping(address => mapping(address => uint256)) private _permissions;

    // Standard ERC20 events
    event Transfer(address indexed from, address indexed to, uint256 amount);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(
        string memory name_,
        string memory symbol_,
        uint8 decimals_,
        uint256 initialSupply_
    ) {
        _tokenName = name_;
        _tokenSymbol = symbol_;
        _tokenDecimals = decimals_;

        // Multiply the initial supply by 10^(decimals)
        _totalTokens = initialSupply_ * 10**uint256(decimals_);

        // Assign the entire initial supply to the deployer
        _balances[msg.sender] = _totalTokens;

        // Emit a Transfer event from the zero address (new tokens) to the deployer
        emit Transfer(address(0), msg.sender, _totalTokens);
    }

    // Public getters for token info
    function tokenName() external view returns (string memory) {
        return _tokenName;
    }

    function tokenSymbol() external view returns (string memory) {
        return _tokenSymbol;
    }

    function tokenDecimals() external view returns (uint8) {
        return _tokenDecimals;
    }

    function totalSupply() external view returns (uint256) {
        return _totalTokens;
    }

    // Returns the balance of a specific account
    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    // Transfers tokens from the caller's address to the recipient
    function sendTokens(address recipient, uint256 amount) external returns (bool) {
        require(recipient != address(0), "Cannot send to the zero address");
        
        uint256 senderBalance = _balances[msg.sender];
        require(senderBalance >= amount, "Insufficient balance");

        _balances[msg.sender] = senderBalance - amount;
        _balances[recipient] += amount;

        emit Transfer(msg.sender, recipient, amount);
        return true;
    }

    // Returns the current allowance of one address to spend another's tokens
    function allowance(address owner, address spender) external view returns (uint256) {
        return _permissions[owner][spender];
    }

    // Approves another address to spend a specified amount of tokens on behalf of the caller
    function approveSpender(address spender, uint256 amount) external returns (bool) {
        _permissions[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    // Transfers tokens using the allowance mechanism
    // `source` must have at least `amount` tokens, and the caller must have at least that allowance
    function sendTokensFrom(
        address source,
        address recipient,
        uint256 amount
    ) external returns (bool) {
        require(source != address(0), "Cannot transfer from the zero address");
        require(recipient != address(0), "Cannot transfer to the zero address");

        uint256 sourceBalance = _balances[source];
        require(sourceBalance >= amount, "Source balance too low");

        uint256 currentAllowance = _permissions[source][msg.sender];
        require(currentAllowance >= amount, "Allowance exceeded");

        _balances[source] = sourceBalance - amount;
        _balances[recipient] += amount;
        _permissions[source][msg.sender] = currentAllowance - amount;

        emit Transfer(source, recipient, amount);
        return true;
    }
}
